'use client';

import { PlusIcon } from 'lucide-react';

import { cn } from '@/lib/utils';
import { NavCount, NavRow, NavSection } from '@/components/ui/workspace-kit/nav';
import { TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import { MiddleTruncate } from '@/components/ui/workspace-kit/middle-truncate';
import type { BucketVisibility, StorageBucket } from '@/components/ui/storage/types';
import { bucketDisplayName, formatCount } from '@/components/ui/storage/utils';
import { VISIBILITY } from '@/components/ui/storage/visibility-badge';

interface BucketRailProps {
	buckets: StorageBucket[];
	selectedBucketId?: string | null;
	onSelectBucket: (bucketId: string) => void;
	onNewBucket?: () => void;
	/** Icon-only rail, as in a collapsed workspace sidebar. */
	collapsed?: boolean;
	/** Heading above the list. */
	title?: string;
	/** Bucket whose contents are loading; its row shows a spinner. */
	busyBucketId?: string | null;
	/** When false, only the selected bucket is enabled, e.g. while policy forbids switching. */
	selectable?: boolean;
	/** Locale for the counts (for example `de-DE`). Default: `en-US`, so the server and the browser agree. */
	locale?: string;
	className?: string;
}

/**
 * `BucketRail` — buckets as workspace nav rows: a visibility glyph, the name,
 * and a quiet object count, with "New bucket" beside the heading. Buckets
 * that are not provisioned yet read muted. Selection is controlled.
 */
export function BucketRail({
	buckets,
	selectedBucketId,
	onSelectBucket,
	onNewBucket,
	collapsed = false,
	title = 'Buckets',
	busyBucketId,
	selectable = true,
	locale,
	className,
}: BucketRailProps) {
	return (
		<div className={cn('flex min-h-0 flex-col', className)}>
			<NavSection
				title={title}
				collapsed={collapsed}
				action={
					onNewBucket ? (
						<TooltipIconButton label="New bucket" size="sm" side={collapsed ? 'right' : 'top'} onClick={onNewBucket}>
							<PlusIcon aria-hidden="true" className="size-3.5" />
						</TooltipIconButton>
					) : null
				}
			>
				{buckets.map((bucket) => {
					const active = bucket.id === selectedBucketId;
					const { icon: Icon, label: visibility } = VISIBILITY[bucket.visibility] ?? VISIBILITY.private;
					const unprovisioned = bucket.provisioned === false;
					const name = bucketDisplayName(bucket);
					const count = bucket.objectCount;
					const details = [
						visibility,
						unprovisioned ? 'not provisioned' : null,
						count != null ? `${formatCount(count, locale)} ${count === 1 ? 'file' : 'files'}` : null,
					]
						.filter(Boolean)
						.join(', ');
					return (
						<NavRow
							key={bucket.id}
							label={`${name}, ${details}`}
							labelNode={
								<>
									{/* The row's own title carries the details; a title here would hide it. */}
									<MiddleTruncate text={name} title={false} />
									<span className="sr-only">, {details}</span>
								</>
							}
							collapsed={collapsed}
							active={active}
							muted={unprovisioned}
							busy={busyBucketId === bucket.id}
							disabled={!selectable && !active}
							leading={<Icon aria-hidden="true" className={cn('size-3.5 shrink-0', active ? 'text-foreground' : 'text-muted-foreground')} />}
							trailing={
								unprovisioned ? (
									<span aria-hidden="true" className="text-[0.6875rem] text-subtle-foreground">
										Off
									</span>
								) : bucket.objectCount != null ? (
									<NavCount value={formatCount(bucket.objectCount, locale)} />
								) : null
							}
							onClick={() => onSelectBucket(bucket.id)}
						/>
					);
				})}
			</NavSection>
		</div>
	);
}

export type { BucketVisibility };
